// Additional original lessons. Twenty parameter sets per model, not official examination papers.
const lessons=[];
const round=x=>Number(x.toFixed(6));
const fact=n=>n<2?1:n*fact(n-1);
const ways=(...entries)=>entries.map(([title,body])=>({title,steps:body.split('|')}));
const q=(prompt,answer,methods,unit='',options=null,visual=null)=>({prompt,answer,ways:methods,unit,options,visual});
function add(id,title,area,topic,level,formula,idea,origin,condition,real,trap,build){lessons.push({id,title,area,topic,level,formula,idea,origin,condition,real,trap,build});}
add('fraction-add','Adding & subtracting fractions','Arithmetic','Number foundations','Foundation','a/b+c/d=(ad+bc)/bd','Fractions must refer to equal-sized parts before their numerators can be added.','Rename both fractions using a common denominator. The renamed pieces have the same size, so their counts can be combined.','Denominators are nonzero. Simplify only common factors of a whole numerator and denominator.','Combine portions of a recipe or fractions of a work shift.','Adding denominators does not preserve the size of a fractional piece.',n=>{let d=n+3,r=3/d;return q(`Evaluate 1/${d} + 2/${d}, rounded to 6 decimals.`,round(r),ways(['Equal parts',`The pieces all have size 1/${d}.|1+2=3 such pieces, so 3/${d}=${round(r)}.`],['Common denominator',`(1×${d}+2×${d})/${d*d}=3/${d}.|Value=${round(r)}.`],['Factor the unit fraction',`(1+2)×(1/${d})=3/${d}.|Value=${round(r)}.`],['Decimal check',`Divide 1 and 2 by ${d}, keeping full precision.|Their sum is ${round(r)} after rounding at the end.`],['Reverse subtraction',`3/${d}−2/${d}=1/${d}.|The proposed sum recovers the first addend.`]));});
add('decimal-multiply','Decimals & place value in products','Arithmetic','Number foundations','Foundation','(a/10)(b/10)=ab/100','A decimal point changes place value, not the multiplication rules.','Represent each one-decimal input as an integer over 10. The product has denominator 100.','Retain place value and round only at the required stage.','Calculate a length-times-width measurement using decimals.','Counting decimal places is a consequence of powers of ten, not a separate multiplication rule.',n=>{let a=n+12,b=5,r=a*b/100;return q(`Evaluate ${(a/10).toFixed(1)} × 0.5.`,r,ways(['Integer product',`${a}×5=${a*5}.|Divide by 100: ${r}.`],['Half the number',`0.5=1/2.|${a/10}÷2=${r}.`],['Fraction product',`(${a}/10)×(5/10).|Cancel 5/10 to 1/2; result=${r}.`],['Distribute',`${a/10} =1+${round(a/10-1)}.|Half each part and add: ${r}.`],['Double to verify',`2×${r}=${a/10}.|This reverses multiplication by 0.5.`]));});
add('divisibility','Divisibility rules: 3 & 9','Arithmetic','Number foundations','Foundation','N mod 9 = digit sum mod 9','Base-ten place values leave remainder 1 when divided by 9. A digit sum therefore preserves the remainder.','10≡1 mod 9, so every power of 10 also equals 1 modulo 9. The same reasoning works modulo 3.','Base-ten nonnegative integers. Apply only the rule for the stated divisor.','Quickly test whether a count can be evenly grouped.','A digit-sum test for 9 is not a test for 7.',n=>{let a=120+n*9,s=String(a).split('').reduce((x,y)=>x+Number(y),0),r=a%9;return q(`Find the remainder when ${a} is divided by 9.`,r,ways(['Digit sum',`Digit sum=${s}.|${s} mod 9=${r}.`],['Nearby multiple',`The lower multiple of 9 is ${a-r}.|Difference=${r}.`],['Place values',`Replace each base-ten place value by remainder 1.|Add digit contributions and reduce modulo 9: ${r}.`],['Reduce from 120',`${a}=120+9×${n}.|120 has remainder 3; full groups of 9 do not change it.`],['Division identity',`${a}=9×${Math.floor(a/9)}+${r}.|The remainder is nonnegative and less than 9.`]));});
add('prime-factors','Prime factorization & divisor counts','Arithmetic','Number foundations','Intermediate','If N=∏pᵢᵃⁱ, divisor count=∏(aᵢ+1)','Each divisor chooses an exponent for every prime factor.','An exponent a allows choices 0 through a, so a+1 choices. Multiplying independent prime-exponent choices counts divisors.','Positive integer N and distinct primes in its factorization.','Count equal-group sizes that divide a stock quantity.','Count repeated prime factors as exponents, not as new primes.',n=>{let a=n%5+1,b=Math.floor(n/5)+1,v=2**a*3**b,r=(a+1)*(b+1);return q(`N=2^${a} ×3^${b} =${v}. How many positive divisors does N have?`,r,ways(['Exponent choices',`Exponent of 2 has ${a+1} choices; exponent of 3 has ${b+1}.|Product=${r}.`],['Grid of divisors',`Create rows 2⁰ through 2^${a}, columns 3⁰ through 3^${b}.|Each cell defines one unique divisor; ${r} cells.`],['Multiply prime-power counts',`2^${a} has ${a+1} divisors; 3^${b} has ${b+1}.|Coprime factors combine independently: ${r}.`],['List by 3 exponent',`For each of ${b+1} powers of 3, choose one of ${a+1} powers of 2.|The disjoint groups total ${r}.`],['Factorization verification',`Every divisor contains only 2 and 3 with exponents within the given bounds.|There are exactly ${r} possible exponent pairs.`]));});
add('square-mental','Squares near a round number','Arithmetic','Mental strategies','Intermediate','(a+b)²=a²+2ab+b²','The square of a sum contains two cross-products, not just two separate squares.','Expand (a+b)(a+b); the two terms ab combine to 2ab.','Use the signed offset from a convenient base.','Compute a square quickly during approximation or an aptitude problem.','(a+b)² is not a²+b².',n=>{let x=21+n,b=x-20,r=x*x;return q(`Find ${x}² using a base of 20.`,r,ways(['Binomial expansion',`400+40×${b}+${b*b}=${r}.`],['Direct multiplication',`${x}×${x}=${r}.`],['Distributive product',`${x}×(20+${b})=${20*x}+${b*x}=${r}.`],['Neighbor difference',`(${x-1})²=${(x-1)**2}.|Add 2×${x-1}+1=${2*x-1}: ${r}.`],['Difference of squares',`${x}²−20²=(${x}−20)(${x}+20)=${b*(x+20)}.|Add 400: ${r}.`]));});
add('unit-conversion','Unit conversions & dimensions','Arithmetic','Number foundations','Foundation','km/h ×5/18 = m/s','Unit conversion changes the numerical representation while keeping the physical quantity fixed.','1 km=1000 m and 1 h=3600 s. Their ratio is 1000/3600=5/18.','Match both numerator and denominator units.','Compare speeds expressed in different measurement systems.','Converting only kilometers while leaving hours unchanged gives the wrong unit.',n=>{let v=36+18*n,r=10+5*n;return q(`Convert ${v} km/h to m/s.`,r,ways(['Conversion factor',`${v}×5/18=${r} m/s.`],['Meters per hour',`${v} km/h=${v*1000} m/h.|Divide by 3600: ${r} m/s.`],['Known 36 anchor',`36 km/h=10 m/s.|${v}/36 ×10=${r}.`],['Cancel first',`${v}/18=${v/18}.|Multiply by 5: ${r}.`],['Reverse check',`${r}×18/5=${v} km/h.|The recovered value matches.`]),'m/s');});
add('reverse-percentage','Reverse percentages & original values','Arithmetic','Ratios & percentages','Intermediate','original = final / growth factor','A reverse percentage asks for the earlier base, not a percentage of the final value.','If final=original×factor, dividing by the nonzero factor recovers the original.','Factor is positive. Identify whether the given final value follows an increase or a decrease.','Recover a price before a stated markup.','Subtracting the same percentage from the final value does not reverse a rise.',n=>{let a=200+40*n,b=1.25*a;return q(`After a 25% increase, a value is ${b}. Find the original value.`,a,ways(['Divide the factor',`${b}/1.25=${a}.`],['Ratio 4:5',`Original:final=100:125=4:5.|${b}/5×4=${a}.`],['Unit percentage',`125% corresponds to ${b}.|1%=${b/125}; 100%=${a}.`],['Equation',`1.25x=${b}.|x=${a}.`],['Forward verification',`25% of ${a}=${a/4}.|${a}+${a/4}=${b}, confirming the base.`]));});
add('marked-profit','Discount with a profit target','Arithmetic','Commercial arithmetic','Intermediate','MP = CP(1+p/100)/(1−d/100)','Markup and discount act on different bases. Find the needed selling price before recovering the marked price.','Profit fixes SP relative to CP. Discount fixes SP relative to MP; equate those two expressions for SP.','Cost positive; discount less than 100%; other charges excluded.','Set a marked price while preserving a target profit under a sale.','Adding profit and discount percentages directly mixes their bases.',n=>{let cp=400+40*n,sp=1.2*cp,mp=sp/.8;return q(`Cost is ₹${cp}. What marked price allows a 20% discount while earning 20% profit?`,round(mp),ways(['Two stages',`Required SP=1.2×${cp}=${sp}.|MP=${sp}/0.8=${round(mp)}.`],['Combined factor',`MP=CP×1.2/0.8=CP×1.5.|${cp}×1.5=${round(mp)}.`],['Ratio chain',`CP:SP=5:6 and SP:MP=4:5.|Combine to CP:MP=2:3; MP=${round(mp)}.`],['Equation',`0.8M=1.2×${cp}.|M=${round(mp)}.`],['Forward check',`80% of ${round(mp)}=${sp}.|The excess over cost is ${round(sp-cp)}, exactly 20% of ${cp}.`]),'rupees');});
add('false-weight','False weights & effective profit','Arithmetic','Commercial arithmetic','Advanced','gain%=(charged weight/actual weight−1)×100','If a seller charges for more weight than delivered at the cost-per-unit price, revenue exceeds the actual cost.','Set the cost of one actual unit to 1. Revenue is charged units; actual cost is delivered units. Compare profit with actual cost.','No stated markup or extra cost; use the actual delivered weight as the profit base.','Diagnose a misleading unit-price transaction.','The missing-weight percentage is not the gain percentage.',n=>{let w=500+10*n,r=(1000/w-1)*100;return q(`At the cost-per-kg price, a seller charges for 1000 g but gives ${w} g. Find effective gain%, rounded to 6 decimals.`,round(r),ways(['Revenue/cost factor',`Revenue/cost=1000/${w}.|Subtract 1 and ×100: ${round(r)}%.`],['Assume a price',`Set cost at ₹1000/kg. Revenue=1000, cost=${w}.|Gain%=(${1000-w}/${w})×100=${round(r)}.`],['Weight difference',`Undelivered weight=${1000-w} g.|Compare that excess charged weight with actual ${w} g: ${round(r)}%.`],['Unit actual weight',`For each actual gram, charged amount is 1000/${w} grams.|Excess proportion=${round(r/100)}, so ${round(r)}%.`],['Reverse cost check',`Actual cost multiplied by (1+gain/100) equals charged value.|${w}×(1000/${w})=1000.`]),'percent');});
add('replacement','Repeated replacement in a mixture','Arithmetic','Averages & mixtures','Advanced','original remaining = V(1−x/V)ⁿ','Removing a well-mixed fraction removes the same fraction of each ingredient. Refill with a different ingredient and repeat.','Each replacement retains factor 1−x/V of the original material. Repeating n times multiplies the same factor n times.','Tank is fully mixed before each removal; volume restored each time; 0≤x≤V.','Model two dilution steps in a fixed-volume container.','Subtracting the same original amount twice ignores the changed concentration.',n=>{let v=40+4*n,x=v/4,r=v*9/16;return q(`A ${v} L tank of juice is mixed. Remove ${x} L and replace with water, twice, mixing each time. How much original juice remains?`,r,ways(['Retention power',`${v}×(3/4)²=${r} L.`],['Step by step',`First remaining=${v*3/4}.|Retain 3/4 again: ${r}.`],['Fraction model',`Each step keeps 75%.|After two, keep 56.25% of ${v}: ${r}.`],['Track removed juice',`First removal takes ${x} L juice.|Second removal takes 3/4 of ${x}=${x*.75} L juice.|Remaining=${v}−${x}−${x*.75}=${r}.`],['Scale a 16-unit model',`16 units become 12 then 9.|Scale 9/16 by ${v}: ${r}.`]),'liters');});
add('average-replacement','Averages after replacing an entry','Arithmetic','Averages & mixtures','Intermediate','new mean = old mean +(new entry−old entry)/count','Replacing one entry changes the total by the difference between its new and old values.','Old total=nm. Add the replacement difference, then divide by unchanged count n.','Group size stays fixed and only the stated entry is replaced.','Update a team’s average after correcting one record.','The total change must be divided across the entire group.',n=>{let m=20+n,old=10,newv=30,r=m+2;return q(`10 entries average ${m}. Replace an entry of 10 with 30. Find the new mean.`,r,ways(['Update total',`Old total=${10*m}.|Add 20 and divide by 10: ${r}.`],['Mean adjustment',`Increase in mean=(30−10)/10=2.|New mean=${m}+2=${r}.`],['Distribute the change',`The extra 20 spreads over 10 entries.|Each equal-share value gains 2, giving ${r}.`],['Equation',`10m_new=10×${m}−10+30.|m_new=${r}.`],['Reverse correction',`Undo the replacement: subtract 20 from new total ${10*r}.|Divide by 10 to recover ${m}.`]));});
add('simple-discount','True discount & present worth','Arithmetic','Commercial arithmetic','Advanced','present worth = due amount/(1+rt/100)','Under simple interest, present worth is the principal that would grow to a future due amount.','Due amount=P+Prt/100=P(1+rt/100). Divide by the simple growth factor; true discount is due minus present worth.','Stated simple interest rate and matching time units; fees excluded.','Compare a future simple-interest payment with its present worth.','True discount and banker’s discount use different bases.',n=>{let p=500+50*n,d=p*1.2;return q(`₹${d} is due after one year at 20% simple interest. Find its present worth.`,p,ways(['Divide growth',`${d}/1.2=${p}.`],['Percent units',`120% corresponds to ${d}.|100%=${d}/120×100=${p}.`],['Ratio method',`Present:due=5:6.|${d}/6×5=${p}.`],['Equation',`P+0.2P=${d}.|1.2P=${d}; P=${p}.`],['Interest check',`20% of ${p}=${p*.2}.|Principal plus interest=${d}.`]),'rupees');});
add('stocks-dividends','Shares, face value & dividend yield','Arithmetic','Commercial arithmetic','Advanced','yield%=annual dividend/market price ×100','Dividend percentage is based on face value; yield compares the cash dividend with the actual market price paid.','Convert the dividend rate into cash using face value, then divide cash by market price.','Simplified stated annual dividend; excludes fees, price changes and taxes.','Distinguish a quoted dividend from the yield at a purchase price.','Using market price as the dividend-rate base confuses two different measures.',n=>{let market=120+5*n,r=10/market*100;return q(`Face value ₹100, annual dividend 10%, market price ₹${market}. Find annual dividend yield%, rounded to 6 decimals.`,round(r),ways(['Cash then yield',`Dividend=10% of 100=₹10.|Yield=10/${market}×100=${round(r)}%.`],['Price ratio',`At face price, yield=10%.|Scale by face/market: 10×100/${market}=${round(r)}%.`],['One-rupee return',`Annual return per invested rupee=10/${market}.|Multiply by 100 for percent: ${round(r)}%.`],['Yield equation',`(${market})×y/100=10.|y=${round(r)}%.`],['Cash reconstruction',`At the exact yield 1000/${market} percent, cash return is 10.|The face-value dividend is recovered.`]),'percent');});
add('compound-ratio','Compound ratios & connected proportions','Arithmetic','Ratios & percentages','Intermediate','If A:B=a:b and B:C=c:d, then A:C=ac:bd','A shared quantity links two ratios after their common term is aligned.','A/B=a/b and B/C=c/d. Multiplying cancels B and gives A/C=ac/(bd).','Shared B refers to the same quantity and is nonzero.','Connect quantities through a common reference measure.','Comparing unaligned middle terms directly can distort the final ratio.',n=>{let a=n+2,r=2*a;return q(`A:B=${a}:3 and B:C=6:1. Find A/C as a number.`,r,ways(['Multiply ratios',`A/C=(A/B)(B/C)=(${a}/3)×6=${r}.`],['Align B',`Scale the first ratio to ${2*a}:6.|With B:C=6:1, A:C=${2*a}:1.`],['Set C=1',`B=6.|A=${a}/3×6=${r}.`],['Common-unit equation',`A=${a}k, B=3k; C=B/6=k/2.|A/C=2×${a}=${r}.`],['Reverse consistency',`Choose C=1, A=${r}, B=6.|A:B reduces to ${a}:3 and B:C is 6:1.`]));});
add('ap-sum-exam','Sum of an arithmetic progression','Quantitative','Equations & sequences','Intermediate','S=n(first+last)/2','Pairing the first and last terms gives the same total as pairing the next two endpoints.','Equal differences ensure endpoint pairs have equal sums. There are n/2 such pair equivalents.','Constant difference and positive integer term count.','Total a savings schedule that increases regularly.','Endpoint averaging fails for a general non-arithmetic sequence.',n=>{let a=n+2,d=3,k=10,last=a+27,r=5*(a+last);return q(`Sum 10 AP terms starting at ${a} with common difference 3.`,r,ways(['Endpoint formula',`Last=${a}+9×3=${last}.|S=10(${a}+${last})/2=${r}.`],['Five pairs',`Each endpoint pair totals ${a+last}.|Five pairs give ${r}.`],['Average term',`Mean=(first+last)/2=${(a+last)/2}.|Ten terms total ${r}.`],['Base plus increments',`Ten initial copies give ${10*a}.|Increments sum to 3(0+…+9)=135.|Total=${r}.`],['Reverse index pairing',`Write the progression forward and backward.|Column sums all equal ${a+last}; two sums total ${2*r}, so one is ${r}.`]));});
add('gp','Geometric progressions','Quantitative','Equations & sequences','Intermediate','aₙ=arⁿ⁻¹','A geometric progression multiplies by the same ratio at each step.','The first term uses zero multiplications. The nth term requires n−1 repeated factors r.','Term index is a positive integer; common ratio is constant.','Model repeated doubling at fixed intervals.','A constant difference is an AP; a constant ratio is a GP.',n=>{let a=n+2,r=a*16;return q(`A GP starts at ${a} with ratio 2. Find its 5th term.`,r,ways(['Power formula',`${a}×2⁴=${r}.`],['Repeated doubling',`${a},${2*a},${4*a},${8*a},${16*a}.|The fifth term is ${r}.`],['Two block jumps',`Two doublings give factor 4.|Repeat that block: ${a}×4×4=${r}.`],['Scale unit GP',`Unit sequence 1,2,4,8,16.|Multiply each term by ${a}; fifth=${r}.`],['Reverse check',`Halve ${r} four times.|You recover the first term ${a}.`]));});
add('simultaneous','Simultaneous linear equations','Quantitative','Equations & sequences','Intermediate','Add or subtract equations to eliminate an unknown','Two independent linear equations can determine two unknowns.','If the same unknown has opposite coefficients, adding the equations removes it and leaves an equation in the other unknown.','A unique solution requires independent equations; check both original equations.','Recover two unit prices from two purchase totals.','Solving one equation alone can leave infinitely many pairs.',n=>{let x=n+4,y=3,s=x+y,d=x-y;return q(`Given x+y=${s} and x−y=${d}, find x.`,x,ways(['Add equations',`2x=${s+d}.|x=${x}.`],['Substitute',`y=${s}−x.|x−(${s}−x)=${d}; 2x=${s+d}.|x=${x}.`],['Average totals',`x is half the sum of (x+y) and (x−y).|(${s}+${d})/2=${x}.`],['Find y first',`Subtract equations: 2y=${s-d}, so y=3.|x=${s}−3=${x}.`],['Verify pair',`Pair (${x},3) gives sum ${s} and difference ${d}.|Both independent equations agree.`]));});
add('races','Races & head starts','Quantitative','Rates & movement','Intermediate','distance ratio = speed ratio for the same elapsed time','When two runners have the same running time, distances are proportional to their constant speeds.','At A’s finish time, B’s distance is vB/vA times the race length. Subtract it from the finish length to get the winning margin.','Simultaneous start, constant speeds, straight course.','Compare race performance under a constant-speed model.','Do not compare distances from different elapsed times.',n=>{let d=100+10*n,r=d/5;return q(`A and B run at speeds in ratio 5:4. When A completes ${d} m, how far behind the finish is B?`,r,ways(['Distance ratio',`B covers 4/5 of ${d}=${d*4/5}.|Margin=${r}.`],['Difference fraction',`Speed gap is 1 of A’s 5 ratio units.|Margin=${d}/5=${r}.`],['Choose speeds',`Use A=5 m/s and B=4 m/s.|A time=${d/5}; B distance=${d*4/5}; margin=${r}.`],['Relative distance',`Over ${d/5} seconds, A gains 1 m per second.|Gain=${r} m.`],['Finish check',`B covered ${d-r}; A covered ${d}.|Their ratio is 4:5, confirming the margin.`]),'meters');});
add('cyclic-work','Work on alternating days','Quantitative','Rates & movement','Advanced','Use complete cycles, then account for the final partial cycle','An alternating schedule does not use the simultaneous combined daily rate.','Compute one full repeated cycle’s work; subtract completed cycles and assign the remainder to the next worker.','A starts; one worker per day; constant rates. Stop as soon as the job is complete.','Plan a rotating staffing schedule.','Using the simultaneous-work formula ignores the alternating schedule.',n=>{let a=2*(n+2),b=2*a,cycles=Math.floor(2*a/3),remaining=1-cycles*3/(2*a),partial=remaining*a,r=2*cycles+(partial<=1?partial:1+(remaining-1/a)*b);return q(`A completes a job in ${a} days, B in ${b} days. They work on alternate days starting with A. Find total days, rounded to 6 decimals.`,round(r),ways(['Two-day cycles',`One cycle completes 1/${a}+1/${b}=3/${2*a}.|${cycles} complete cycles leave ${round(remaining)} job.|Finish the remainder in the next scheduled day(s): total ${round(r)}.`],['Integer work units',`Job=${2*a} units; A=2/day, B=1/day.|Each two-day cycle gives 3 units.|Use ${cycles} cycles, then ${2*a-cycles*3} units remain; total ${round(r)} days.`],['Schedule accumulation',`After ${2*cycles} days, completed=${cycles*3}/${2*a}.|Next A can do 2 units, followed by B if needed.|The earliest completion is ${round(r)} days.`],['Completion bound',`The work is unfinished immediately before the final scheduled portion.|Using that worker’s own rate yields ${round(r)} days; simultaneous rates would be invalid.`],['Work verification',`Complete cycles contribute ${cycles*3} work units.|The final scheduled portion contributes ${2*a-cycles*3} units.|Total=${2*a}, confirming ${round(r)} days.`]),'days');});
add('escalator','Moving walkways & relative motion','Quantitative','Rates & movement','Intermediate','ground speed = walking speed + belt speed','A moving surface carries a walker in addition to the walker’s own movement relative to it.','In one second the belt moves b distance units and the walker adds w relative units; the ground displacement is their signed sum.','Same-direction constant speeds, all units compatible.','Model travel on a moving airport walkway.','A walking speed relative to the belt is not the ground speed.',n=>{let l=30+3*n,w=2,b=1,r=l/3;return q(`A ${l} m walkway moves at 1 m/s. You walk in the same direction at 2 m/s relative to it. Find crossing time.`,r,ways(['Ground speed',`Speed=2+1=3 m/s.|Time=${l}/3=${r} s.`],['Distance equation',`Walker adds 2t and belt adds t.|3t=${l}, so t=${r}.`],['One-second model',`Each second advances 3 m relative to ground.|${l} m needs ${r} seconds.`],['Contribution split',`At completion, walking contributes ${2*r} m and belt ${r} m.|Sum=${l}; elapsed=${r} s.`],['Reverse check',`${r}×3=${l} m.|The combined displacement covers the walkway.`]),'seconds');});
add('triangle-area-exam','Triangles & perpendicular height','Quantitative','Geometry & measurement','Foundation','A=bh/2','A triangle has half the area of a parallelogram with the same base and perpendicular height.','Join two congruent triangles to form a parallelogram. Splitting its bh area equally gives bh/2.','Use perpendicular height, not a sloping side. Positive dimensions.','Estimate triangular coverage or a triangular garden section.','A displayed side length need not be the height.',n=>{let b=n+5,h=6,r=b*3;return q(`A triangle has base ${b} cm and perpendicular height 6 cm. Find its area.`,r,ways(['Area formula',`${b}×6/2=${r}.`],['Half a parallelogram',`Matching parallelogram area=${b*6}.|Half is ${r}.`],['Halve height first',`6/2=3.|${b}×3=${r}.`],['Split the base',`Split ${b} into 2 and ${b-2}.|Triangle areas 6 and ${3*(b-2)} total ${r}.`],['Recover height',`2A/b=2×${r}/${b}=6.|The original perpendicular height is recovered.`]),'cm²');});
add('heron','Heron’s formula','Quantitative','Geometry & measurement','Advanced','A=√[s(s−a)(s−b)(s−c)], s=(a+b+c)/2','Three side lengths can determine triangle area without a separately given height.','Combining the cosine law with A=ab sin(C)/2 and simplifying gives the four semiperimeter factors.','Positive sides must satisfy triangle inequalities; retain exact roots when needed.','Find a triangular plot’s area from its measured sides.','If the triangle inequality fails, the sides do not form a triangle.',n=>{let k=n+1,r=6*k*k;return q(`A triangle has sides ${3*k}, ${4*k}, ${5*k} cm. Find its area.`,r,ways(['Heron substitution',`s=${6*k}.|A=√[${6*k}×${3*k}×${2*k}×${k}]=${r}.`],['Right-triangle recognition',`The sides scale the 3–4–5 right triangle.|Area=${3*k}×${4*k}/2=${r}.`],['Scaling the area',`A 3–4–5 triangle has area 6.|Scale lengths by ${k}; area scales by ${k*k}, giving ${r}.`],['Height from Pythagoras',`With base ${4*k}, perpendicular leg is ${3*k}.|Half their product=${r}.`],['Squared-area check',`Heron’s product is ${r*r}.|Its nonnegative square root is ${r}, consistent with positive triangle area.`]),'cm²');});
add('polygon-angles','Polygon interior angles','Quantitative','Geometry & measurement','Intermediate','interior angle sum=(n−2)×180°','A simple polygon can be divided into triangles without changing its total interior angle sum.','Triangulate from one vertex in a convex polygon: n−2 triangles each contribute 180°. The same sum holds for simple polygons.','Simple planar polygon; n≥3. Regularity is only needed to infer equal individual angles.','Check angles in a polygonal design.','The interior sum differs from the 360° sum of consistently oriented exterior turns.',n=>{let k=n+3,r=(k-2)*180;return q(`Find the sum of interior angles of a convex ${k}-sided polygon.`,r,ways(['Triangle count',`${k}−2=${k-2} triangles.|${k-2}×180=${r}°.`],['Exterior turns',`Straight angles at vertices total ${k*180}.|Subtract 360° exterior turns: ${r}°.`],['Add a vertex',`A triangle starts at 180°.|Each additional vertex adds 180°; total=${r}.`],['Algebraic form',`180n−360=180×${k}−360=${r}.`],['Regular representative',`A regular ${k}-gon has each interior angle ${round(r/k)}°.|Multiplying the exact per-angle value by ${k} gives ${r}°; the sum does not require regularity.`]),'degrees');});
add('sector-area','Sectors & portions of circles','Quantitative','Geometry & measurement','Intermediate','sector area=(θ/360)πr²','A sector’s area occupies the same fraction of a circle as its central angle occupies of a full turn.','Equal angle sectors in a circle have equal area by rotation symmetry; the area fraction is θ/360.','Angle in degrees, 0≤θ≤360; radius positive.','Estimate coverage of a circular slice.','Arc length and sector area have different dimensions.',n=>{let r=n+2,v=Math.PI*r*r/4;return q(`A 90° sector has radius ${r}. Find its area, rounded to 6 decimals.`,round(v),ways(['Fraction of circle',`90/360=1/4.|Quarter of π×${r*r} is ${round(v)}.`],['Direct substitution',`(90/360)×π×${r}²=${round(v)}.|Keep π unrounded until the last step.`],['Four equal sectors',`Four identical sectors cover the full circle of area ${r*r}π.|Divide by 4: ${round(v)}.`],['Unit-sector scaling',`A radius-1 quarter-circle has area π/4.|Radius ${r} scales area by ${r*r}; result=${round(v)}.`],['Recover the circle',`The exact sector area is ${r*r}π/4.|Multiply by 4 to recover ${r*r}π, the full circle area.`]),'square units');});
add('surface-area','Cuboid surface area','Quantitative','Geometry & measurement','Intermediate','TSA=2(lw+lh+wh)','A cuboid has three pairs of matching rectangular faces.','Add one face area for each pair, then double the sum. This counts all six surfaces once.','Closed cuboid, positive matching units; openings require subtracting removed faces.','Estimate wrapping or paint for a rectangular box.','Surface area is not volume and uses square units.',n=>{let l=n+3,w=2,h=4,r=2*(l*w+l*h+w*h);return q(`Find total surface area of a closed cuboid ${l}×2×4 cm.`,r,ways(['Three pairs',`2(${2*l}+${4*l}+8)=${r}.`],['Top/bottom and sides',`Top/bottom=${4*l}; front/back=${8*l}; ends=16.|Total=${r}.`],['Net rectangles',`Lay out six faces: ${l}×2 twice, ${l}×4 twice, 2×4 twice.|Their sum=${r}.`],['Factor repeated length',`TSA=2[l(2+4)+8]=12l+16.|At l=${l}, result=${r}.`],['Lateral plus bases',`Lateral area=2(l+2)×4=${8*(l+2)}.|Add two base areas ${4*l}: ${r}.`]),'cm²');});
add('cone-volume','Cones: volume','Quantitative','Geometry & measurement','Intermediate','V=πr²h/3','A cone has one third of the volume of a cylinder with the same circular base and perpendicular height.','Cross-sections scale quadratically with distance from the tip; summing their areas over the height gives one third of base×height.','Right circular cone; perpendicular height, positive dimensions.','Estimate the capacity of a conical container.','Slant height belongs to surface-area calculations, not this volume formula.',n=>{let r=n+2,h=3,v=Math.PI*r*r;return q(`A cone has radius ${r} cm and perpendicular height 3 cm. Find volume, rounded to 6 decimals.`,round(v),ways(['Formula',`π×${r}²×3/3=${r*r}π.|Rounded value=${round(v)}.`],['Matching cylinder',`Cylinder volume=3π×${r*r}.|One third is ${r*r}π=${round(v)}.`],['Cancel height factor',`h/3=1.|Volume is π×${r*r}=${round(v)}.`],['Reference cone',`A radius-1 height-3 cone has volume π.|Scale radius by ${r}; volume factor=${r*r}, giving ${round(v)}.`],['Recover height',`Using exact V=${r*r}π, h=3V/(πr²).|This returns 3, the given perpendicular height.`]),'cm³');});
add('sphere-volume','Spheres: volume','Quantitative','Geometry & measurement','Intermediate','V=4πr³/3','Sphere volume scales with the cube of its radius.','Integrating circular cross-sections π(r²−x²) from −r to r gives 4πr³/3.','Positive radius and compatible units. Use the stipulated π or retain it exactly.','Compare volumes of spherical containers.','Doubling radius multiplies volume by eight, not two.',n=>{let r=n+1,v=4*Math.PI*r**3/3;return q(`Find the volume of a sphere of radius ${r}, rounded to 6 decimals.`,round(v),ways(['Substitute',`4π×${r}³/3=${4*r**3}π/3.|Rounded value=${round(v)}.`],['Constant times cube',`Compute r³=${r**3}, then multiply by 4π/3.|Result=${round(v)}.`],['Unit-sphere scaling',`Unit sphere volume=4π/3.|Scale by ${r}³=${r**3}, giving ${round(v)}.`],['Cylinder comparison',`Matching cylinder radius ${r}, height ${2*r} has volume ${2*r**3}π.|Sphere is 2/3 of that cylinder: ${round(v)}.`],['Recover radius',`Using exact V, cube root of 3V/(4π) equals cube root of ${r**3}.|This returns radius ${r}.`]),'cubic units');});
add('similarity','Similar figures & area ratios','Quantitative','Geometry & measurement','Intermediate','area ratio = (corresponding length ratio)²','Similarity preserves angles and scales all corresponding lengths by the same factor.','Scaling horizontal and vertical lengths by k multiplies a two-dimensional area by k².','Figures are similar, not merely equal in one dimension.','Scale plans, photographs or similar geometric designs.','Area ratio is the square of the side ratio.',n=>{let a=n+2,b=a+1,r=(b/a)**2;return q(`Two similar figures have small:large side ratio ${a}:${b}. Find large area/small area, rounded to 6 decimals.`,round(r),ways(['Square scale',`Length factor=${b}/${a}.|Square it: ${round(r)}.`],['Normalized lengths',`Take small side ${a}, large ${b}.|Corresponding areas are proportional to ${a*a} and ${b*b}.|Ratio=${round(r)}.`],['Two dimension factors',`Each dimension scales by ${b}/${a}.|Product of the two factors=${round(r)}.`],['Triangle area model',`Scale both base and height by ${b}/${a}.|The 1/2 factor cancels in the area ratio, leaving ${round(r)}.`],['Reverse ratio',`Small/large area=(${a}/${b})².|Invert to get large/small=${round(r)}.`]));});
add('height-distance','Heights & distances','Quantitative','Geometry & measurement','Intermediate','tan θ = height / horizontal distance','The angle of elevation relates a vertical height to a horizontal distance through a right triangle.','By similar triangles, opposite/adjacent is fixed for a fixed angle. Rearranging tan θ=h/d gives h=d tan θ.','Flat horizontal ground; sightline starts at ground level in these examples. Add observer height when specified.','Estimate a vertical height from a surveyed distance and elevation angle.','Use horizontal distance rather than slant sightline in the tangent ratio.',n=>{let d=10+n,r=d;return q(`From ground level ${d} m horizontally from a tower, elevation angle is 45°. Find tower height.`,r,ways(['Tangent',`tan45°=1.|h=${d}×1=${r}.`],['Isosceles right triangle',`A 45°–45°–90° triangle has equal legs.|Vertical leg equals horizontal ${d}.`],['Ratio equation',`h/${d}=1.|h=${r}.`],['Slope model',`The sightline slope is 1.|A horizontal run ${d} has vertical rise ${d}.`],['Geometry check',`The two acute angles are both 45°.|Equal opposite sides confirm height ${r}.`]),'meters');});
add('coordinate-slope','Coordinates & slope','Quantitative','Geometry & measurement','Intermediate','slope=(y₂−y₁)/(x₂−x₁)','Slope measures signed vertical change per horizontal unit.','For a straight line, similar rise-run triangles have the same ratio Δy/Δx.','Different x coordinates; vertical lines have undefined slope.','Interpret a constant rate from a graph.','Changing point order requires changing both numerator and denominator signs.',n=>{let x=n+1,y=n+2,r=2;return q(`Find slope through (${x},${y}) and (${x+3},${y+6}).`,r,ways(['Difference ratio',`Δy=6; Δx=3.|Slope=6/3=2.`],['Rise-run picture',`Three units right corresponds to six units up.|Each horizontal unit raises y by 2.`],['Line equation',`Use y=mx+b at both points.|Subtract equations: 6=3m, so m=2.`],['Reverse point order',`Use (−6)/(−3).|Both signs cancel, giving 2.`],['Midpoint check',`Midpoint changes x by 1.5 and y by 3 from the first point.|Its rise/run is still 2.`]));});
add('binomial-count','Independent repeated trials','Quantitative','Counting & chance','Advanced','P(exactly k)=C(n,k)pᵏ(1−p)ⁿ⁻ᵏ','An exact-success probability counts which trial positions succeed, then multiplies the probability of each pattern.','Choose k success positions among n. Each pattern has k success factors p and n−k failure factors 1−p.','Independent trials with the same success probability.','Model repeated independent quality tests.','Using the binomial model for dependent sampling can be wrong.',n=>{let p=(n+1)/25,r=3*p*p*(1-p);return q(`Three independent trials each succeed with probability ${(n+1)}/25. Find P(exactly 2 successes), rounded to 6 decimals.`,round(r),ways(['Binomial formula',`C(3,2)p²(1−p)=3×${p}²×${1-p}.|Result=${round(r)}.`],['List patterns',`SSF,SFS,FSS are the three disjoint patterns.|Each has probability ${round(p*p*(1-p))}; retain exact values before summing to ${round(r)}.`],['Locate the failure',`Choose the single failure position in 3 ways.|Multiply by two successes and one failure: ${round(r)}.`],['Polynomial form',`3p²−3p³.|Substitute p=${p}: ${round(r)}.`],['Complement check',`Exclude 0,1 and 3 successes from probability 1.|1−(1−p)³−3p(1−p)²−p³=${round(r)}.`]),'probability');});
const people=['Asha','Bala','Chitra','Dev','Esha','Farah','Gopal','Hari','Isha','Jai','Kiran','Leela','Maya','Neel','Omar','Pia','Qadir','Riya','Sara','Tara'];
add('alphabet-rank','Alphabet positions & reverse ranks','Reasoning','Patterns & codes','Foundation','forward rank + reverse rank =27','A letter’s ranks count from opposite ends of the 26-letter English alphabet.','Adding both ranks counts the letter twice, so the sum is 26+1.','English A–Z only; no zero-based indexing.','Decode position-based letter clues.','Reverse rank is 27−rank, not 26−rank.',n=>{let a=n+1,c=String.fromCharCode(64+a),r=27-a;return q(`What is the rank of ${c} counting from Z=1 backward?`,r,ways(['Rank sum',`Forward rank=${a}.|Reverse=27−${a}=${r}.`],['Count after it',`There are ${26-a} letters after ${c}.|Include ${c} itself: ${r}.`],['Index complement',`A–Z positions are 1–26.|Mirror position ${a} to ${r}.`],['Endpoint distance',`Distance in positions from ${c} to Z is ${26-a}.|Inclusive backward rank is one larger: ${r}.`],['Reverse check',`27−${r}=${a}.|This recovers the forward rank of ${c}.`]));});
add('word-formation','Word formation from letter inventories','Reasoning','Patterns & codes','Foundation','A target is possible iff every letter count fits the inventory','A letter may be used only as many times as it appears in the source inventory.','Match each target letter to a distinct available copy. If one required count exceeds supply, formation fails.','Reordering allowed; no extra copies or substitutions.','Check whether an inventory contains enough components for a task.','Seeing a letter once does not allow using it twice.',n=>{let k=n+1;return q(`An inventory contains ${k} A letters and ${k+1} B letters. Can it form a target with ${k+1} A letters and ${k} B letters?`,'No',ways(['Count A first',`Need ${k+1} A copies, have ${k}.|One A is missing; formation is impossible.`],['Inventory subtraction',`A remainder=${k}−${k+1}=−1.|A negative remainder means failure.`],['Matching copies',`All ${k} A copies can be matched.|The extra target A has no source copy, so No.`],['B does not fix A',`There is one spare B.|It cannot replace the missing A under the stated rule.`],['Necessary condition',`Every target count must be at most its inventory count.|The A inequality fails, proving impossibility.`]),'', ['No','Yes','Only by reordering','Only if B comes first']);});
add('letter-count','Letter-position arithmetic codes','Reasoning','Patterns & codes','Intermediate','word value = sum of stated letter weights','A numeric code needs an explicit rule, because many arbitrary mappings can fit one example.','Under A=1,…,Z=26, adding letter positions computes the assigned word value.','Use the stated additive rule; no unstated shifts.','Read an illustrative label checksum.','A code example alone may not uniquely define the mapping.',n=>{let a=n+1,c=String.fromCharCode(64+a),r=2*a+2;return q(`A=1,…,Z=26; word value is the sum of positions. Find the value of ${c}B${c}.`,r,ways(['Three-position sum',`${a}+2+${a}=${r}.`],['Repeated-letter factor',`Two ${c} letters contribute 2×${a}.|Add B=2: ${r}.`],['Start from B',`Start with 2.|Add ${a} twice: ${r}.`],['Expression rule',`For position x, x+2+x=2x+2.|Substitute x=${a}: ${r}.`],['Reverse check',`(${r}−2)/2=${a}.|This matches the repeated letter’s position.`]));});
add('seating-facing','Facing direction in seating clues','Reasoning','Spatial & arrangement','Intermediate','Facing south reverses a person’s left and right on a north-up diagram','Left and right are relative to the person’s orientation.','When facing south, the person’s right points west and left points east on a north-up map.','The diagram is north-up and the stated person faces south.','Read an arrangement clue without reversing it incorrectly.','The observer’s right need not be the seated person’s right.',n=>q(`${people[n]} faces south in a north-up diagram. Their right-hand neighbor lies in which compass direction?`,'West',ways(['Body orientation',`Turn to face south.|Your right points west.`],['Compass rotation',`Facing north, right is east.|Rotate 180° to face south; right becomes west.`],['Coordinate model',`Forward is negative north.|Right is negative east, which is west.`],['Diagram view',`Draw the person looking down a north-up map.|The right-hand seat is on the map’s left, west.`],['Opposite-side check',`A south-facing person’s left is east.|The opposite right side must be west.`]),'', ['West','East','North','South']));
add('floor-puzzle','Floor puzzles & vertical constraints','Reasoning','Spatial & arrangement','Intermediate','Place fixed endpoints, then immediate-above/below blocks','Vertical puzzles combine exact placements with relative order constraints.','An immediate-above clue fixes the floor difference to 1; endpoints provide an anchor.','Floors are numbered from bottom upward. One person per floor.','Plan assignments subject to positional constraints.','Above and immediately above mean different things.',n=>{let top=n+4,r=top-1;return q(`${people[n]} occupies floor ${top}. Ravi is immediately below them. Floors are numbered upward from 1. Which floor is Ravi on?`,r,ways(['One-step subtraction',`Immediately below means one lower floor.|${top}−1=${r}.`],['Number line',`Move one step down from floor ${top}.|Arrive at ${r}.`],['Difference equation',`${top}−R=1.|R=${r}.`],['Place a block',`The two-floor block is Ravi below ${people[n]}.|Upper=${top}, lower=${r}.`],['Reverse check',`One floor above ${r} is ${top}.|The immediate-below clue is satisfied.`]));});
add('scheduling','Scheduling & ordering constraints','Reasoning','Spatial & arrangement','Intermediate','Build a precedence chain; avoid adding unstated adjacent constraints','A scheduling rule can specify earlier/later without specifying exact neighboring positions.','Represent “before” as a directed edge. Composing edges yields necessary order; missing edges may leave freedom.','These examples give a full three-task chain. Tasks occupy separate times.','Order tasks with dependencies.','Before does not automatically mean immediately before.',n=>{let a='Task '+(n+1),b='Task '+(n+21),c='Task '+(n+41);return q(`${a} occurs before ${b}; ${b} occurs before ${c}. Which task must be last among these three?`,c,ways(['Chain order',`${a} → ${b} → ${c}.|${c} must be last.`],['Transitivity',`${a} is before ${c} through ${b}.|Both other tasks precede ${c}.`],['Directed graph',`Edges point toward the later task.|${c} has both predecessors and no later task.`],['Eliminate others',`${a} cannot be last because ${b} follows it.|${b} cannot be last because ${c} follows it.`],['Construct and verify',`Arrange ${a},${b},${c}.|Both clues hold and the last task is ${c}.`]),'', [c,a,b,'Cannot determine']);});
add('relations-maternal','Family relations: maternal branches','Reasoning','Spatial & arrangement','Intermediate','Mother’s brother = maternal uncle','A family relation can be composed through an intermediate person.','Travel from the child to the mother, then to the mother’s brother. Generation and stated gender identify the relationship.','Use only stated relationships; names do not imply gender.','Interpret a multi-step family connection.','An uncle may be maternal or paternal depending on the connecting parent.',n=>q(`${people[n]} is Ravi’s mother. Dev is her brother. How is Dev related to Ravi?`,'Maternal uncle',ways(['Compose the links',`Dev is the brother of Ravi’s mother.|That relation is maternal uncle.`],['Start from Ravi',`Go one generation up to the mother.|Her brother is Ravi’s maternal uncle.`],['Family tree',`Place mother and Dev as siblings, Ravi below mother.|Dev is a male relative one generation above, maternal uncle.`],['Generation check',`Dev is not Ravi’s sibling or child.|His sibling link to the mother identifies maternal uncle.`],['Eliminate branches',`The connecting parent is the mother, not father.|Choose maternal rather than paternal uncle.`]),'', ['Maternal uncle','Paternal uncle','Brother','Grandfather']));
add('syllogism-some','Syllogisms with “some”','Reasoning','Logic & deduction','Intermediate','Some A are B and all B are C ⇒ some A are C','An existential premise gives at least one actual member in an overlap.','The A-and-B witness must also belong to C because every B is C. That same witness proves an A-and-C overlap.','“Some” means at least one. No converse universals are inferred.','Trace whether a stated overlap guarantees another overlap.','An existential witness does not prove that all A belong to C.',n=>q(`Some group A${n+1} members are B${n+1}. All B${n+1} are C${n+1}. Must some A${n+1} be C${n+1}?`,'Yes',ways(['Witness chain',`Choose the member guaranteed in A and B.|All B are C, so that member is in A and C.`],['Set containment',`B lies inside C.|The nonempty A∩B region lies within A∩C, so Yes.`],['Implication on the witness',`The witness satisfies A and B.|B→C gives A and C.`],['Contradiction',`Suppose no A were C.|The given A-and-B witness would be outside C, contradicting all B are C.`],['Existence check',`The first premise explicitly supplies a member.|Unlike empty-set universal chains, this conclusion has an actual witness.`]),'', ['Yes','No','Only if all A are B','Cannot determine']));
add('assumptions','Statements & necessary assumptions','Reasoning','Logic & deduction','Advanced','A necessary assumption must hold for the stated argument to work','An assumption is an unstated bridge between premises and a conclusion. Test whether denying it breaks that bridge.','For a claim relying on identical productivity, the assumption of unchanged per-worker rate is necessary for the calculation used.','Evaluate this argument’s specific reasoning, not every plausible real-world assumption.','Assess a staffing claim before accepting its calculation.','An assumption is not merely a desirable outcome.',n=>q(`A manager says: “${n+4} workers finish in 10 days, so twice as many will finish in 5.” Which assumption is necessary for this proportional calculation?`,'Same per-worker rate',ways(['Identify the model',`The argument keeps workers×days constant.|That requires unchanged per-worker rate.`],['Negation test',`If each worker slows when the team doubles, the 5-day inference fails.|So equal productivity is necessary for this calculation.`],['Rate equation',`Work=N×rate×time.|The calculation cancels rate only if it is unchanged.`],['Counterexample',`Suppose doubled staff each works at half speed.|Team rate stays unchanged and still needs 10 days, breaking the claim.`],['Eliminate unrelated claims',`Worker names or equal salaries do not establish productivity.|The relevant bridge is same per-worker rate.`]),'', ['Same per-worker rate','All workers have equal names','Work becomes smaller','Everyone is paid twice as much']));
add('logic-sufficiency','Reasoning data sufficiency','Reasoning','Logic & deduction','Advanced','Information is sufficient when all valid models agree on the answer','A statement is sufficient only when it forces one requested conclusion.','Construct valid arrangements satisfying each statement. If they give different requested answers, the statement is insufficient.','Consider each statement alone before their combination; positions are distinct.','Decide whether enough ordering information has been supplied.','Knowing that A is early does not identify the final position.',n=>{let a=people[n];return q(`Who is last among ${a}, Ravi, Tara? I: ${a} is before Ravi. II: Ravi is before Tara. Which data is sufficient?`,'Both together only',ways(['Test I',`I allows ${a},Ravi,Tara and Tara,${a},Ravi.|Last can differ; I alone is insufficient.`],['Test II',`II allows ${a},Ravi,Tara and Ravi,Tara,${a}.|Last can differ; II alone is insufficient.`],['Combine',`Together: ${a} before Ravi before Tara.|Tara is forced last.`],['Constraint graph',`I supplies A→R; II supplies R→T.|Both edges form a complete three-person chain.`],['Countermodel check',`No order satisfying both can put someone after Tara.|Only the combination forces the answer.`]),'', ['I alone','II alone','Both together only','Neither even together']);});
add('mirror','Mirror images on a coordinate grid','Reasoning','Time & visual reasoning','Intermediate','Reflection in the y-axis: (x,y)→(−x,y)','A vertical mirror reverses horizontal position while preserving vertical position.','The reflected point lies the same perpendicular distance on the opposite side of the mirror line.','Mirror is the y-axis; coordinates use a fixed orientation.','Identify a reflected point or diagram.','A y-axis reflection reverses x, not y.',n=>{let x=n+1,y=3,r=`(${-x}, ${y})`;return q(`Reflect (${x}, ${y}) in the y-axis. What point results?`,r,ways(['Coordinate rule',`Negate x, preserve y.|Point=${r}.`],['Equal distance',`Original is ${x} units right of the mirror.|Move ${x} units left at height ${y}: ${r}.`],['Horizontal number line',`At fixed y=${y}, mirror x=${x} to x=${-x}.|Result=${r}.`],['Midpoint condition',`Original and image midpoint must be on x=0.|Their x values sum to zero and y stays 3.`],['Double reflection',`Reflect ${r} again to recover (${x},3).|The original point confirms the image.`]),'', [r,`(${x}, ${-y})`,`(${-x}, ${-y})`,`(${y}, ${x})`],{type:'reflection',values:[x,y],labels:['Original','Mirror']} );});
add('water-image','Water images & horizontal reflection','Reasoning','Time & visual reasoning','Intermediate','Reflection in the x-axis: (x,y)→(x,−y)','A horizontal reflecting line reverses vertical position and preserves horizontal position.','The reflected point lies at equal perpendicular distance below or above the x-axis.','Mirror is the x-axis; a water-image model is a geometric horizontal reflection.','Distinguish horizontal reflection from a vertical mirror.','Do not reverse both coordinates unless the transformation calls for it.',n=>{let x=n+2,y=4,r=`(${x}, ${-y})`;return q(`Reflect (${x}, ${y}) in the x-axis. What point results?`,r,ways(['Coordinate rule',`Preserve x and negate y.|Point=${r}.`],['Equal vertical distance',`Move from y=4 to y=−4 at x=${x}.|Result=${r}.`],['Vertical number line',`Reflect 4 around 0 to −4.|Keep horizontal coordinate ${x}.`],['Midpoint',`Original and image midpoint is (${x},0).|The x-axis bisects their vertical separation.`],['Reverse check',`Reflect ${r} a second time.|Recover (${x},4), verifying the result.`]),'', [r,`(${-x}, ${y})`,`(${-x}, ${-y})`,`(${y}, ${x})`]);});
add('paper-fold','Paper folding & symmetric hole counts','Reasoning','Time & visual reasoning','Intermediate','One clean fold doubles a non-crease interior punch','Unfolding reproduces a punched hole at its reflected location.','A single fold stacks two layers. One punch through both layers creates two distinct holes when unfolded, unless it lies on the crease or coincides.','One fold; punches off the crease and away from edges; punched locations and their mirrors are distinct.','Predict the symmetry of a folded design.','A punch on a crease does not follow the distinct two-hole model.',n=>{let k=n+1,r=2*k;return q(`Paper is folded once. ${k} distinct interior holes are punched through both layers, off the crease, with distinct mirror locations. How many holes after unfolding?`,r,ways(['Layer count',`Each punch cuts 2 layers.|${k}×2=${r} holes.`],['Reflection pairs',`Every original punch has one mirror copy.|${k} pairs total ${r}.`],['Disjoint groups',`One side has ${k}; the reflected side has ${k}.|Total=${r}.`],['Unitary model',`1 off-crease punch produces 2 holes.|${k} produce ${r}.`],['Refold verification',`${r} unfolded holes pair into ${k} coinciding punch positions when folded.|This matches the given punches.`]));});
add('dice','Dice & opposite faces','Reasoning','Time & visual reasoning','Intermediate','For the stated standard die, opposite faces sum to 7','A standard numbered die has fixed opposite pairs: 1–6, 2–5 and 3–4.','The opposite-sum convention encodes those pairs. It is given here so no orientation or ambiguous custom die needs to be inferred.','Use only for a die explicitly stated to have opposite sums 7. General dice need their own net or views.','Distinguish a specified dice convention from an inferred arrangement.','Adjacent faces are not opposite; a custom die may use a different convention.',n=>{let a=n%6+1,die=Math.floor(n/6)+1,r=7-a;return q(`Die ${die} follows the opposite-faces-sum-to-7 convention. Face ${a} is on top. Which face is opposite?`,r,ways(['Subtract from 7',`7−${a}=${r}.`],['Pair table',`Opposite pairs are 1–6,2–5,3–4.|Face ${a} pairs with ${r}.`],['Pair equation',`${a}+x=7.|x=${r}.`],['Eliminate other values',`Only ${r} produces the specified sum 7 with ${a}.|That determines the opposite face.`],['Symmetry check',`Opposite of ${r} is 7−${r}=${a}.|The pair relation is mutual.`]));});
add('line-chart','Line charts & absolute changes','Data','Tables & charts','Foundation','absolute change = later−earlier','A line chart’s vertical difference measures change in its plotted unit, not automatically a growth percentage.','Subtract the earlier y-value from the later one after checking axis units and time labels.','The graph values use the same definition and unit. Interpolation needs a separately stated model.','Read the increase in a monthly measure.','A steep visual line can be misleading when axes are truncated.',n=>{let a=50+5*n,b=a+20;return q(`A line chart shows January ${a} units and February ${b}. What is the absolute increase?`,20,ways(['Subtract values',`${b}−${a}=20.`],['Count forward',`From ${a} to ${b}, add 20.|The increase is 20 units.`],['Difference equation',`${a}+d=${b}.|d=20.`],['Reference comparison',`Treat January as the baseline 0 change.|February lies 20 units above it.`],['Reverse check',`${b}−20=${a}.|The earlier value is recovered.`]),'units',null,{type:'columns',values:[a,b],labels:['January','February']});});
add('pie-chart','Pie charts & central angles','Data','Tables & charts','Foundation','category angle = share ×360°','A pie chart maps the full amount to one complete turn.','If a category is fraction f of the total, its rotational slice is fraction f of 360°.','Shares are nonnegative and sum to 1; use disjoint categories.','Convert a share into a circle sector angle.','A percentage must be divided by 100 before multiplying 360.',n=>{let p=5+n,r=p*3.6;return q(`A category represents ${p}% of a pie chart. Find its central angle.`,round(r),ways(['Percent to fraction',`${p}/100×360=${round(r)}°.`],['One percent angle',`1% of a full turn is 3.6°.|${p}×3.6=${round(r)}°.`],['Proportion',`Angle/360=${p}/100.|Angle=${round(r)}°.`],['Ratio units',`100 percentage units span 360°.|${p} units span ${round(r)}°.`],['Reverse share',`${round(r)}/360×100=${p}%.|The original share is recovered.`]),'degrees');});
add('stacked-chart','Stacked bars & subgroup totals','Data','Tables & charts','Intermediate','bar total = sum of its disjoint segments','A stacked bar places different category amounts one above another.','The height represents the sum when the segments share an amount scale. A 100% stacked chart represents proportions instead.','Here the chart is an amount chart and segments are disjoint.','Interpret product segments within a monthly total.','Do not confuse a 100% stacked chart with a raw amount chart.',n=>{let a=20+n,b=30+n,c=40+n,r=a+b+c;return q(`A raw stacked bar has segments ${a}, ${b}, ${c} units. Find its total.`,r,ways(['Add all segments',`${a}+${b}+${c}=${r}.`],['Endpoints plus middle',`${a}+${c}=${a+c}.|Add ${b}: ${r}.`],['Reference value',`Use 3 copies of middle ${b}.|Deviations −10,0,+10 cancel; total=${r}.`],['Accumulate height',`After two segments: ${a+b}.|Final height after adding ${c}: ${r}.`],['Recover a segment',`${r}−${a}−${b}=${c}.|The last segment agrees with the total.`]),'units',null,{type:'bar',values:[a,b,c],labels:['Segment A','Segment B','Segment C']});});
add('missing-data','Missing values from a total','Data','Tables & charts','Foundation','missing = total − sum of known entries','If a total covers mutually exclusive entries, the unknown entry is the part left after subtracting all known parts.','total=known1+known2+missing. Rearrange to isolate missing.','The total and entries refer to the same group and unit; no overlaps.','Complete a table from its row total.','A subtotal that overlaps known rows cannot simply be subtracted again.',n=>{let a=20+n,b=30+n,c=15+n,t=a+b+c;return q(`A row total is ${t}; known entries are ${a} and ${b}. Find the third entry.`,c,ways(['Subtract known sum',`${t}−(${a}+${b})=${c}.`],['Sequential subtraction',`${t}−${a}=${t-a}.|Subtract ${b}: ${c}.`],['Equation',`${a}+${b}+x=${t}.|x=${c}.`],['Complement share',`Known part=${a+b}.|The remaining part of the full total is ${c}.`],['Forward verify',`${a}+${b}+${c}=${t}.|All disjoint entries reproduce the row total.`]),'units');});
add('median','Median & ordered data','Data','Statistics & summaries','Foundation','Odd count median = middle ordered value','The median splits an ordered data set into lower and upper halves.','With 2k+1 ordered values, k lie before position k+1 and k after it. That middle value is the median.','Sort first; for an even count use the mean of the two middle values.','Summarize a typical ordered value when extremes distort the mean.','The middle position in an unsorted list is not necessarily the median.',n=>{let m=n+20,v=[m+4,m-3,m,m+1,m-2];return q(`Find the median of ${v.join(', ')}.`,m,ways(['Sort',`Order: ${m-3},${m-2},${m},${m+1},${m+4}.|Third value=${m}.`],['Count around candidate',`Two values are below ${m}, two above.|Therefore ${m} is the middle.`],['Remove extremes',`Remove ${m-3} and ${m+4}.|Then remove ${m-2} and ${m+1}; remaining=${m}.`],['Position rule',`Five entries give median position (5+1)/2=3.|Sorted position 3 is ${m}.`],['Selection check',`No other value has two entries on both sides.|The order-statistic condition uniquely selects ${m}.`]));});
add('mode','Mode & frequency','Data','Statistics & summaries','Foundation','Mode = most frequent value','The mode summarizes the value that appears most often.','Build a frequency count for each distinct value and compare the counts.','Data may have multiple modes or no unique mode; this example has a unique mode.','Identify the most common size or response in a list.','The largest value is not automatically the most common.',n=>{let m=n+10,v=[m,m+1,m,m+2,m];return q(`Find the mode of ${v.join(', ')}.`,m,ways(['Frequency table',`${m} appears 3 times; others once.|Mode=${m}.`],['Tally',`Place three tally marks at ${m}.|No other value reaches that count.`],['Group identical values',`Group ${m},${m},${m}; the two remaining values differ.|Largest group is ${m}.`],['Eliminate singletons',`${m+1} and ${m+2} appear only once.|${m} is the unique repeated maximum-frequency value.`],['Count verification',`Frequencies 3+1+1=5 match all entries.|The unique maximum count identifies ${m}.`]));});
add('range-data','Range & spread','Data','Statistics & summaries','Foundation','range = maximum−minimum','The range measures the distance between the two extreme observations.','Any interval containing the data must reach from its smallest to largest value. Their difference is the range.','Same measurement units; range is sensitive to outliers.','Compare the observed spread of daily values.','Range does not describe how data are distributed between the extremes.',n=>{let a=n+5,v=[a,a+4,a+7,a+2],r=7;return q(`Find the range of ${v.join(', ')}.`,r,ways(['Extremes',`Max=${a+7}; min=${a}.|Difference=7.`],['Shift the baseline',`Subtract ${a} from all entries: 0,4,7,2.|Range=7−0=7.`],['Number-line span',`Lowest and highest points are ${a} and ${a+7}.|Their separation is 7.`],['Sort endpoints',`Sorted endpoints remain ${a},${a+7}.|Subtract to get 7.`],['Reverse span check',`Minimum ${a} plus range 7 gives maximum ${a+7}.|The extrema agree.`]));});
add('combined-data','Combining two data sets','Data','Statistics & summaries','Intermediate','combined mean = (n₁m₁+n₂m₂)/(n₁+n₂)','A combined mean must account for the sizes of both groups.','Recover each group’s total from count×mean, then add totals and divide by the combined count.','Disjoint groups; same variable and unit.','Combine regional performance summaries.','An unweighted average of group means ignores different group sizes.',n=>{let a=30+n,b=a+10,r=a+6;return q(`20 entries average ${a}; 30 more average ${b}. Find the combined mean.`,r,ways(['Recover totals',`Total=20×${a}+30×${b}=${50*r}.|Divide by 50: ${r}.`],['Weighted fractions',`Weights are 2/5 and 3/5.|(2×${a}+3×${b})/5=${r}.`],['Lower reference',`Start all 50 at ${a}.|30 entries add 10 each; mean gains 300/50=6, yielding ${r}.`],['Balance deviations',`At ${r}, lower group deficit=20×6=120.|Upper group surplus=30×4=120, balancing exactly.`],['Group ratio',`Group sizes reduce to 2:3.|Two copies of ${a} and three of ${b} average ${r}.`]));});
add('caselet','Caselets & translating prose to a table','Data','Tables & charts','Intermediate','Build the disjoint category table before calculating','A caselet hides its data table in prose. Organize the facts into labeled quantities.','If categories are disjoint and exhaustive, their fractions add to 1. The remaining fraction defines the unspecified category.','All percentages use the same full group, with no overlap.','Extract category counts from a short business or survey paragraph.','Mixed percentage bases cannot be added as shares of one total.',n=>{let t=200+20*n,r=t*.5;return q(`A company has ${t} staff: 30% sales, 20% support, the rest engineering, with disjoint departments. How many engineers?`,r,ways(['Remaining percentage',`100−30−20=50%.|Half of ${t}=${r}.`],['Subtract counts',`Sales=${t*.3}; support=${t*.2}.|${t}−${t*.3}−${t*.2}=${r}.`],['Table model',`Rows: sales 30%, support 20%, engineering 50%.|Engineering count=0.5×${t}=${r}.`],['Combine known groups',`Sales+support is 50%.|The other 50% contains ${r} staff.`],['Reconstruct total',`${t*.3}+${t*.2}+${r}=${t}.|All department counts add to the full staff.`]),'people');});
add('data-ratio','Cross-category ratios in data','Data','Tables & charts','Intermediate','comparison ratio = category A / category B','A ratio compares two category quantities; its base is the second category, not the whole total.','Divide both amounts by a common unit or factor to preserve their relative size.','Same units and positive denominator category.','Compare outputs of two branches.','Part-to-part and part-to-whole ratios answer different questions.',n=>{let k=n+4,a=3*k,b=2*k,r=1.5;return q(`Branch A produces ${a} units; B produces ${b}. Find A/B.`,r,ways(['Direct division',`${a}/${b}=1.5.`],['Cancel common factor',`Amounts are 3×${k} and 2×${k}.|Ratio=3/2=1.5.`],['Common units',`Measure output in groups of ${k}.|A has 3 groups, B has 2; A/B=1.5.`],['Excess over B',`A exceeds B by ${k}, half of B.|A/B=1+0.5=1.5.`],['Reverse amount check',`1.5×${b}=${a}.|The ratio reconstructs A.`]));});
export const expandedExamLessons=lessons;
